model EventEnvelope {
  specversion: string = "1.0";
  id: string;
  type: string = "Inventory.StockReserved";
  source: string = "/inventory/reservations";
  data: EventData;
}

model EventData {
  reservation: StockReservation;
}

model StockReservation {
  variantReference: string;
  locationReference: string;
  reference: string;
  quantity: int32;
  status: ReservationStatus;
  expiresAt?: utcDateTime;
}

enum ReservationStatus {
  Active: "active",
  Released: "released",
  Expired: "expired",
  Consumed: "consumed",
}
